import{_ as e,a as r,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 47 困：资源耗竭时保存判断至比较与自测","description":"结合《周易》经传与《周易正义》，理解损益的尺度、相遇与聚集、困顿与持续供养。","frontmatter":{"title":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 47 困：资源耗竭时保存判断至比较与自测","description":"结合《周易》经传与《周易正义》，理解损益的尺度、相遇与聚集、困顿与持续供养。","splitFrom":"life/personal/yijing/hexagrams-41-48.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井","summary":"结合《周易》经传与《周易正义》，理解损益的尺度、相遇与聚集、困顿与持续供养。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 44 姤：相遇之际先辨关系至46 升：积累生长也须知止","link":"/life/personal/yijing/hexagrams-41-48-part-02"},"next":{"text":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅","link":"/life/personal/yijing/hexagrams-49-56"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 44 姤：相遇之际先辨关系至46 升：积累生长也须知止","link":"/life/personal/yijing/hexagrams-41-48-part-02"},"next":{"text":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅","link":"/life/personal/yijing/hexagrams-49-56"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-41-48-part-03.md","filePath":"life/personal/yijing/hexagrams-41-48-part-03.md"}'),o={name:"life/personal/yijing/hexagrams-41-48-part-03.md"};function i(s,t,d,l,p,g){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读-四十一至四十八-损、益、夬、姤、萃、升、困、井-·-47-困-资源耗竭时保存判断至比较与自测" tabindex="-1">六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 47 困：资源耗竭时保存判断至比较与自测 <a class="header-anchor" href="#六十四卦详读-四十一至四十八-损、益、夬、姤、萃、升、困、井-·-47-困-资源耗竭时保存判断至比较与自测" aria-label="Permalink to &quot;六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 47 困：资源耗竭时保存判断至比较与自测&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-41-48">返回分篇目录</a></p><p>本篇逐卦列出卦辞、六爻和大象。<strong>原文</strong>保留古字，<strong>白话概括</strong>为现代原创说明；解释主要参照王弼注、孔颖达疏《周易正义》。它们分别属于经文、传文与后世注释，不宜混成同一时代的一段话。卦符的六爻自下而上读，上下卦的自然象是解释线索，不能当作现代自然科学机制。</p><p>损益涉及付出与受益的方向，夬姤涉及决断与相遇，萃升涉及聚集与生长，困井则把个人困顿引向持续供养。读“吉凶”时保留古代占筮语境；现实选择仍需事实、资源与具体责任。</p><h2 id="gua-47" tabindex="-1">47 困：资源耗竭时保存判断 <a class="header-anchor" href="#gua-47" aria-label="Permalink to &quot;47 困：资源耗竭时保存判断 {#gua-47}&quot;">​</a></h2><p><strong>卦符：䷮｜上卦兑 ☱（泽），下卦坎 ☵（水、险）。</strong> 水在泽下，泽面无水，《象传》由此表现失去滋养的困顿。</p><p><strong>卦辞原文：</strong></p><blockquote><p>困：亨，貞大人吉，无咎，有言不信。</p></blockquote><p><strong>白话概括：</strong> 身处困厄，仍可讨论怎样保持正当、取得通路；此时言语未必获得相信。《正义》以“不改其操”解释困中之亨，把它放在品行维持上，不只是物质困难立即消失。古注的道德区分也有局限，今天不应以是否脱困衡量人格高下。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>臀困于株木，入于幽谷，三歲不覿。</td><td>坐于枯木、深入幽谷、长久不见，描写失去支持与隔绝；“三岁”不可直接当作现实困境期限。</td></tr><tr><td>九二</td><td>困于酒食，朱紱方來，利用亨祀，征凶，无咎。</td><td>宴饮或供养之事也能成困，贵者来临；目前适合以诚相接，急于出行仍凶，不能只见资源不见约束。</td></tr><tr><td>六三</td><td>困于石，據于蒺藜，入于其宮，不見其妻，凶。</td><td>前遇石、后倚刺，回家又失去亲近支持，多重错置构成凶境；不据此预测配偶失踪。</td></tr><tr><td>九四</td><td>來徐徐，困于金車，吝，有終。</td><td>想来相助却行动迟缓，受车所困，有遗憾而可有终；“徐徐、金车”据古注，电子本有异文。</td></tr><tr><td>九五</td><td>劓刖，困于赤紱，乃徐有說，利用祭祀。</td><td>刑伤与官服并列，显示尊位仍有困；后来渐得解除，“说”在此依古注作解脱之义。</td></tr><tr><td>上六</td><td>困于葛藟，于臲卼，曰動悔。有悔，征吉。</td><td>被藤蔓缠绕、处境不稳，怕动会悔；能反思并改变，行动才可能改善，不必把困境视为永恒。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>澤无水，困；君子以致命遂志。</p></blockquote><p><strong>大象解释：</strong> 古注解释为守志至死，属于古代强烈的伦理理想。现代阅读可讨论坚定与价值，但不应要求困顿者牺牲生命，更不能用它拒绝求助、治疗或安全保护。</p><p><strong>整体读法与误区：</strong> 本卦的酒食、车服与幽谷表明困不只有贫乏一种形态，也可能是依赖、阻隔与失去信任。“有言不信”提醒空言有限，却不意味着受困者应沉默。现实中可用证据、援助和制度渠道增加被理解的机会；上六的可动性也让全卦留有变化空间。</p><p><strong>经传对读：</strong> 九二和九五都有祭祀，表明资源和礼制关系尚未完全消失；九四虽然来得迟缓，仍保留“有终”。上六又把“动悔”与“有悔”并置，需要区分害怕行动和发现确有需要反思之处。逐项寻找尚可借助的条件，能避免把困字读成全无希望，也避免用一句乐观话遮住实际耗竭。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9B%B0" target="_blank" rel="noopener noreferrer">《周易·困》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/05%E5%9B%B0" target="_blank" rel="noopener noreferrer">《周易正义》卷五·困</a>。</p><h2 id="gua-48" tabindex="-1">48 井：让共同资源真正可用 <a class="header-anchor" href="#gua-48" aria-label="Permalink to &quot;48 井：让共同资源真正可用 {#gua-48}&quot;">​</a></h2><p><strong>卦符：䷯｜上卦坎 ☵（水），下卦巽 ☴（木、入）。</strong> 以木具入水而提水，是古注的井象；井既是物，也是共同生活的持续供给。</p><p><strong>卦辞原文：</strong></p><blockquote><p>井：改邑不改井，无喪无得，往來井井。汔至亦未繘井。羸其瓶，凶。</p></blockquote><p><strong>白话概括：</strong> 聚落可能迁改，井的供养功能仍在；取水快完成时，若绳具未妥、瓶又损坏，劳动仍会落空。《正义》以“已出为功”解释这一警告：资源存在与资源真正送到需要者手中，是两件相关但不同的事。“汔”近，“繘”是汲水绳。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>井泥不食，舊井无禽。</td><td>井底污泥使水不能饮，旧井连禽鸟也不来；服务能力丧失，不能只靠曾经有用的名声。</td></tr><tr><td>九二</td><td>井谷射鮒，瓮敝漏。</td><td>井中只有小鱼，取水瓮又破漏；具备一点资源却缺少合适承接，无法完成供养。</td></tr><tr><td>九三</td><td>井渫不食，為我心惻，可用汲，王明，並受其福。</td><td>清淘后的井仍无人使用，令人惋惜；如果主事者明察，可以让众人共同受益。“渫”读 xiè。</td></tr><tr><td>六四</td><td>井甃，无咎。</td><td>修砌井壁，暂在维护阶段，也有必要；“甃”读 zhòu，维护本身是可靠供给的一环。</td></tr><tr><td>九五</td><td>井冽，寒泉食。</td><td>水清而凉，可以饮用；井德由实际可用表现，不只是外表修饰。</td></tr><tr><td>上六</td><td>井收勿幕，有孚元吉。</td><td>汲水到上而不遮盖阻用，供养开放而可信；“收”的训释有别，核心是完成供给、让人可取。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>木上有水，井；君子以勞民勸相。</p></blockquote><p><strong>大象解释：</strong> 慰劳或勤勉民众，劝导彼此相助；“劳”的读法与侧重需结合古注，不能只译成命令人多劳动。井的功用建立在修井、汲水与互助之上。</p><p><strong>整体读法与误区：</strong> 从污井、漏器、清井未用到修壁、寒泉和开放，适合比较公共资源的不同状态，却不是所有项目都必经的线性流程。现代可联想到饮水设施、公共知识或社区服务：不仅有资源，还要可获取、可维护、有人受益。古文“不改井”强调常德，不是要求设备、制度和技术永不更新。</p><p><strong>经传对读：</strong> 九三的“可用汲”与九五的“寒泉食”不同：前者已有条件却未被使用，后者才真正进入生活。六四修壁夹在两者之间，说明维护可能暂时不产出水，却支持长期可用。最后“不幕”又把问题转向开放程度；资源好坏、设施完备和使用机会，因而成为三个可分别检查的层面。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E4%BA%95" target="_blank" rel="noopener noreferrer">《周易·井》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/05%E4%BA%95" target="_blank" rel="noopener noreferrer">《周易正义》卷五·井</a>。</p><h2 id="比较与自测" tabindex="-1">比较与自测 <a class="header-anchor" href="#比较与自测" aria-label="Permalink to &quot;比较与自测 {#比较与自测}&quot;">​</a></h2><ol><li>损与益以谁为尺度命名？为什么“损”不等于一切付出，“益”不等于无限增加？</li><li>夬要求决断，却为什么说“不利即戎”？姤的《彖传》为何又肯定相遇？</li><li>萃九五与井九三分别如何表现“有位置／有资源，却尚未取得效果”？</li><li>升上六与困上六，对不断前进和害怕行动分别提出了什么限制？</li></ol><p>继续阅读：<a href="/life/personal/yijing/hexagrams-49-56">第四十九至五十六卦</a> · 返回 <a href="/life/personal/yijing/overview">易经专题导读</a>。</p>',33)])])}const u=e(o,[["render",i]]);export{c as __pageData,u as default};
